#include <string>
#include <unordered_map>
#include <mutex>
#include <chrono>
#include <vector>
#include <functional>
#include <cstring>
#include <ctime>
#include <openssl/hmac.h>
#include <openssl/sha.h>

namespace orchestrator {

struct ServiceIdentity {
    std::string service_name;
    std::string namespace_id;
    std::string instance_id;
    uint64_t issued_at;
    uint64_t expires_at;
};

struct CacheEntry {
    ServiceIdentity identity;
    bool authenticated;
    std::chrono::steady_clock::time_point cached_at;
    uint32_t access_count;
    std::string token_mac;  // Store full MAC for cache validation
};

class AuthTokenVerifier {
public:
    static bool verify_hmac(const std::string& token, const std::string& secret) {
        if (token.size() < 64) return false;
        std::string payload = token.substr(0, token.size() - 32);
        std::string provided_mac = token.substr(token.size() - 32);

        unsigned char computed[32];
        unsigned int len = 32;
        HMAC(EVP_sha256(), secret.data(), secret.size(),
             reinterpret_cast<const unsigned char*>(payload.data()),
             payload.size(), computed, &len);

        return CRYPTO_memcmp(computed, provided_mac.data(), 32) == 0;
    }
};

class ServiceAuthCache {
private:
    std::unordered_map<std::string, CacheEntry> cache_;
    std::mutex mutex_;
    std::chrono::seconds ttl_{300};
    size_t max_entries_{10000};

    std::string compute_cache_key(const std::string& token) {
        // Cache key is derived from the ENTIRE token content
        // This ensures different tokens always map to different cache entries
        unsigned char hash[SHA256_DIGEST_LENGTH];
        SHA256(reinterpret_cast<const unsigned char*>(token.data()),
               token.size(), hash);
        return std::string(reinterpret_cast<char*>(hash), SHA256_DIGEST_LENGTH);
    }

    static uint64_t current_unix_time() {
        return static_cast<uint64_t>(::time(nullptr));
    }

public:
    ServiceAuthCache() = default;

    struct AuthResult {
        bool authorized;
        ServiceIdentity identity;
        bool from_cache;
    };

    AuthResult authenticate_service(const std::string& token,
                                     const std::string& claimed_service,
                                     const std::string& claimed_namespace,
                                     const std::string& hmac_secret) {
        std::string cache_key = compute_cache_key(token);

        // Check cache first
        {
            std::lock_guard<std::mutex> lock(mutex_);
            auto it = cache_.find(cache_key);
            if (it != cache_.end()) {
                auto& entry = it->second;
                auto now = std::chrono::steady_clock::now();
                // Reject entries whose underlying token has expired.
                if (now - entry.cached_at < ttl_ &&
                    entry.identity.expires_at > current_unix_time()) {
                    // Verify claimed identity matches cached identity
                    if (entry.identity.service_name == claimed_service &&
                        entry.identity.namespace_id == claimed_namespace) {
                        entry.access_count++;
                        return {entry.authenticated, entry.identity, true};
                    }
                    // Claimed identity mismatch - reject
                    return {false, {}, true};
                } else {
                    cache_.erase(it);
                }
            }
        }

        // Cache miss - perform full verification
        bool valid = AuthTokenVerifier::verify_hmac(token, hmac_secret);

        ServiceIdentity identity;
        if (valid) {
            // Only trust token-embedded identity after HMAC verification
            identity.service_name = extract_service_name(token);
            identity.namespace_id = extract_namespace(token);
            identity.instance_id = extract_instance_id(token);
            identity.issued_at = extract_timestamp(token);
            identity.expires_at = identity.issued_at + 3600;

            // Enforce token expiration.
            if (identity.expires_at <= current_unix_time()) {
                valid = false;
            }

            // Verify claimed identity matches token-embedded identity
            if (identity.service_name != claimed_service ||
                identity.namespace_id != claimed_namespace) {
                valid = false;
            }
        }

        // Cache the result
        {
            std::lock_guard<std::mutex> lock(mutex_);
            if (cache_.size() < max_entries_ && valid) {
                CacheEntry entry;
                entry.identity = identity;
                entry.authenticated = valid;
                entry.cached_at = std::chrono::steady_clock::now();
                entry.access_count = 1;
                entry.token_mac = token.substr(token.size() - 32);
                cache_[cache_key] = entry;
            }
        }

        return {valid, identity, false};
    }

    void invalidate_service(const std::string& service_name,
                            const std::string& namespace_id) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto it = cache_.begin(); it != cache_.end();) {
            if (it->second.identity.service_name == service_name &&
                it->second.identity.namespace_id == namespace_id) {
                it = cache_.erase(it);
            } else {
                ++it;
            }
        }
    }

private:
    std::string extract_service_name(const std::string& token) {
        // Extract from verified token payload
        if (token.size() < 64) return "";
        // Service name encoded at offset 40, length-prefixed
        uint8_t len = static_cast<uint8_t>(token[40]);
        if (41 + len > token.size() - 32) return "";
        return token.substr(41, len);
    }

    std::string extract_namespace(const std::string& token) {
        if (token.size() < 64) return "";
        uint8_t svc_len = static_cast<uint8_t>(token[40]);
        size_t ns_offset = 41 + svc_len;
        if (ns_offset >= token.size() - 32) return "";
        uint8_t ns_len = static_cast<uint8_t>(token[ns_offset]);
        if (ns_offset + 1 + ns_len > token.size() - 32) return "";
        return token.substr(ns_offset + 1, ns_len);
    }

    std::string extract_instance_id(const std::string& token) {
        if (token.size() < 48) return "";
        return token.substr(16, 16);
    }

    uint64_t extract_timestamp(const std::string& token) {
        if (token.size() < 48) return 0;
        uint64_t ts = 0;
        memcpy(&ts, token.data() + 32, sizeof(ts));
        return ts;
    }
};

class ContainerOrchestrator {
private:
    ServiceAuthCache auth_cache_;
    std::string cluster_secret_;
    std::unordered_map<std::string, std::vector<std::string>> service_permissions_;

public:
    ContainerOrchestrator(const std::string& secret) : cluster_secret_(secret) {}

    bool handle_service_request(const std::string& auth_token,
                                const std::string& source_service,
                                const std::string& source_namespace,
                                const std::string& target_service,
                                const std::string& action) {
        auto result = auth_cache_.authenticate_service(
            auth_token, source_service, source_namespace, cluster_secret_);

        if (!result.authorized) return false;

        // Check if source service has permission to access target
        auto perm_key = result.identity.service_name + "/" + 
                        result.identity.namespace_id;
        auto it = service_permissions_.find(perm_key);
        if (it == service_permissions_.end()) return false;

        std::string required = target_service + ":" + action;
        for (const auto& perm : it->second) {
            if (perm == required || perm == target_service + ":*") {
                return true;
            }
        }
        return false;
    }
};

} // namespace orchestrator
